import sys
M = 1_000_000_007

def fib(n):
    # fast doubling, iterative from top bit
    a, b = 0, 1  # F(k), F(k+1), k=0
    for bit in bin(n)[2:]:
        # k -> 2k
        c = a * ((b << 1) - a) % M
        d = (a * a + b * b) % M
        if bit == '1':
            a, b = d, (c + d) % M
        else:
            a, b = c, d
    return a

if __name__ == "__main__":
    print(fib(int(sys.argv[1])))
